package com.hostel.hostelmanagement.entity; import com.hostel.hostelmanagement.enums.ComplaintStatus; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class Complaint { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String title; @Column(length=2000) String description; @ManyToOne User student; @Enumerated(EnumType.STRING) ComplaintStatus status=ComplaintStatus.OPEN; LocalDateTime createdAt=LocalDateTime.now(); public Complaint(){} public Long getId(){return id;} public String getTitle(){return title;} public String getDescription(){return description;} public User getStudent(){return student;} public ComplaintStatus getStatus(){return status;} public LocalDateTime getCreatedAt(){return createdAt;} public void setId(Long v){id=v;} public void setTitle(String v){title=v;} public void setDescription(String v){description=v;} public void setStudent(User v){student=v;} public void setStatus(ComplaintStatus v){status=v;} }